/* CommonJS-compatible bytes executed by `node -e`; stdin is carrier-only. */
const fsp=require("node:fs/promises"),crypto=require("node:crypto"),path=require("node:path"),os=require("node:os"),{execFileSync}=require("node:child_process");
const PROD_ROOT="/opt/ynx-release-control-plane/creator-studio-3f97a13d";
const ORDER=Object.freeze(["release-upgrade-executor-3f97a13d.mjs","release-candidates/candidate-3f97a13d/creator-studio.tar","release-candidates/candidate-0e1a53c5/creator-studio.tar"]);
const EXPECTED=Object.freeze({
  "release-upgrade-executor-3f97a13d.mjs":{bytes:16279,sha256:"05f5372e368f74512f7142d70d6160d28ca5e9a7dbab6f555076f1af2874e1b9",mode:0o700},
  "release-candidates/candidate-3f97a13d/creator-studio.tar":{bytes:159232,sha256:"b99c791393bba7b9a0780fe13ac4c61104754a2766d12fb3990af15b447aec89",mode:0o600},
  "release-candidates/candidate-0e1a53c5/creator-studio.tar":{bytes:159232,sha256:"3f56aa4c3f9d87d27f7cdf19eafc0dacf1da78d83d31def2080f0162d92bdf8a",mode:0o600}
});
const sha=b=>crypto.createHash("sha256").update(b).digest("hex"),stable=v=>JSON.stringify(v),mode=s=>s.mode&0o7777;
async function absent(p){try{await fsp.lstat(p);throw Error("PATH_NOT_ABSENT:"+p)}catch(e){if(e.code!=="ENOENT")throw e}}
async function identity(p){const s=await fsp.lstat(p);if(!s.isFile()||s.nlink!==1)throw Error("NON_ORDINARY_FILE:"+p);const b=await fsp.readFile(p);return{dev:String(s.dev),ino:String(s.ino),uid:s.uid,gid:s.gid,mode:mode(s),nlink:s.nlink,bytes:b.length,sha256:sha(b)}}
async function directoryIdentity(p){const s=await fsp.lstat(p);if(!s.isDirectory()||s.isSymbolicLink())throw Error("NON_ORDINARY_DIRECTORY:"+p);return{dev:String(s.dev),ino:String(s.ino),uid:s.uid,gid:s.gid,mode:mode(s),nlink:s.nlink}}
async function stdin(){const chunks=[];for await(const chunk of process.stdin)chunks.push(chunk);return Buffer.concat(chunks)}
function decode(raw){let value;try{value=JSON.parse(raw.toString("utf8"))}catch{throw Error("CARRIER_JSON_INVALID")}if(stable(value)+"\n"!==raw.toString("utf8")||value.schemaVersion!=="1.0.0"||stable(value.objects?.map(o=>o.name))!==stable(ORDER))throw Error("CARRIER_NOT_CANONICAL");for(const object of value.objects){const expected=EXPECTED[object.name],bytes=Buffer.from(object.base64,"base64");if(!expected||object.bytes!==expected.bytes||object.sha256!==expected.sha256||object.mode!==expected.mode||bytes.length!==expected.bytes||sha(bytes)!==expected.sha256||bytes.toString("base64")!==object.base64)throw Error("CARRIER_OBJECT_INVALID:"+object.name);object.bytesDecoded=bytes}return value}
async function tree(root){const values=[];const walk=async(rel="")=>{for(const name of(await fsp.readdir(path.join(root,rel))).sort()){const next=path.join(rel,name),s=await fsp.lstat(path.join(root,next));if(s.isSymbolicLink())throw Error("PLACEMENT_SYMLINK:"+next);values.push((s.isDirectory()?"d:":"f:")+next);if(s.isDirectory())await walk(next)}};await walk();return values.sort()}
const EXPECTED_TREE=Object.freeze(["f:placement.receipt.json","f:release-upgrade-executor-3f97a13d.mjs","d:release-candidates","d:release-candidates/candidate-0e1a53c5","f:release-candidates/candidate-0e1a53c5/creator-studio.tar","d:release-candidates/candidate-3f97a13d","f:release-candidates/candidate-3f97a13d/creator-studio.tar"].sort());
async function validate(root){const receipt=JSON.parse(await fsp.readFile(path.join(root,"placement.receipt.json"),"utf8"));if(receipt.schemaVersion!=="1.0.0"||receipt.status!=="PLACED_AWAITING_FORWARD"||receipt.root!==root||stable(await tree(root))!==stable(EXPECTED_TREE))throw Error("PLACEMENT_RECEIPT_INVALID");for(const name of ORDER)if(stable(await identity(path.join(root,name)))!==stable(receipt.objects[name]))throw Error("PLACEMENT_OBJECT_SUBSTITUTED:"+name);return receipt}


async function placeSimple(raw,root=PROD_ROOT){const carrier=decode(raw),stage=root+".next";await absent(root);await absent(stage);await fsp.mkdir(stage,{mode:0o700});try{const objects={};for(const object of carrier.objects){const target=path.join(stage,object.name);await fsp.mkdir(path.dirname(target),{recursive:true,mode:0o700});await fsp.writeFile(target,object.bytesDecoded,{flag:"wx",mode:object.mode});await fsp.chmod(target,object.mode);objects[object.name]=await identity(target)}const receipt={schemaVersion:"1.0.0",status:"PLACED_AWAITING_FORWARD",root,carrier:{bytes:raw.length,sha256:sha(raw)},objects},receiptPath=path.join(stage,"placement.receipt.json");await fsp.writeFile(receiptPath,stable(receipt)+"\n",{flag:"wx",mode:0o600});await fsp.rename(stage,root);return validate(root)}catch(error){await fsp.rm(stage,{recursive:true,force:true});throw error}}
async function forward(raw,root=PROD_ROOT){const placement=await placeSimple(raw,root),executor=path.join(root,ORDER[0]);try{const output=execFileSync(process.execPath,[executor,"forward"],{encoding:"utf8"});return{status:"PLACED_FORWARD_SUCCEEDED_ROLLBACK_RETAINED",placement,executorOutput:JSON.parse(output)}}catch(error){const message=error.stderr?Buffer.from(error.stderr).toString("utf8").trim():error.message;throw Error("FORWARD_FAILED_RUNTIME_EXECUTOR_HANDLED_ROLLBACK:"+message)}}
async function rollback(root=PROD_ROOT){const placement=await validate(root),executor=path.join(root,ORDER[0]),output=execFileSync(process.execPath,[executor,"rollback"],{encoding:"utf8"});return{status:"CONDITIONAL_ROLLBACK_SUCCEEDED",placement,executorOutput:JSON.parse(output)}}
function carrier(objects){return Buffer.from(stable({schemaVersion:"1.0.0",objects:ORDER.map(name=>{const bytes=objects[name],expected=EXPECTED[name];return{name,mode:expected.mode,bytes:bytes.length,sha256:sha(bytes),base64:bytes.toString("base64")}})})+"\n")}
async function fixture(repoRoot){const root=await fsp.mkdtemp(path.join(os.tmpdir(),"ynx-creator-3f97-transport-")),target=path.join(root,"control"),objects={"release-upgrade-executor-3f97a13d.mjs":await fsp.readFile(path.join(repoRoot,"release-upgrade-executor-3f97a13d.mjs")),"release-candidates/candidate-3f97a13d/creator-studio.tar":await fsp.readFile(path.join(repoRoot,"release-candidates/candidate-3f97a13d/creator-studio.tar")),"release-candidates/candidate-0e1a53c5/creator-studio.tar":await fsp.readFile(path.join(repoRoot,"release-candidates/candidate-0e1a53c5/creator-studio.tar"))},raw=carrier(objects);try{const placed=await placeSimple(raw,target),executorResult=JSON.parse(execFileSync(process.execPath,[path.join(target,ORDER[0]),"fixture"],{encoding:"utf8"}),),substitution=path.join(target,ORDER[0]),original=await fsp.readFile(substitution);await fsp.rm(substitution);await fsp.writeFile(substitution,original,{mode:0o700});const substitutedRejected=await validate(target).then(()=>false,()=>true);if(executorResult.fixture!=="passed"||!substitutedRejected)throw Error("TRANSPORT_FIXTURE_GATE_FAILED");console.log(JSON.stringify({fixture:"passed",carrier:{bytes:raw.length,sha256:sha(raw)},placementStatus:placed.status,executorFixture:executorResult.fixture,substitutedPlacementRejected:substitutedRejected,exactForwardArgv:["/usr/bin/sudo","-n","/usr/bin/node","-e","eval(Buffer.from(process.argv[1],\"base64\").toString(\"utf8\"))","<literal-transport-base64>","place-forward"],exactRollbackArgv:["/usr/bin/sudo","-n","/usr/bin/node","-e","eval(Buffer.from(process.argv[1],\"base64\").toString(\"utf8\"))","<literal-transport-base64>","rollback"]},null,2))}finally{await fsp.rm(root,{recursive:true,force:true})}}
async function main(){const command=process.argv[2];if(command==="fixture")return fixture(process.argv[3]);if(command==="place-forward")return process.stdout.write(stable(await forward(await stdin()))+"\n");if(command==="rollback")return process.stdout.write(stable(await rollback())+"\n");throw Error("USAGE: fixture <repoRoot>|place-forward|rollback")}
main().catch(error=>{process.stderr.write(error.stack+"\n");process.exitCode=1});
